import pandas as pd
df = pd.read_csv(${item})
schema_report = {
    'columns': [{'name': col, 'dtype': str(df[col].dtype)} for col in df.columns],
    'row_count': len(df),
    'issues': []
}
for col in df.columns:
    if df[col].dtype == 'object':
        try:
            pd.to_numeric(df[col])
            schema_report['issues'].append(f'Column {col} might be numeric but is stored as object')
        except:
            pass
env['schema_report'] = schema_report

import pandas as pd
df = pd.read_csv(${item})
issues = []
missing = df.isnull().sum()
for col, count in missing.items():
    if count > 0:
        issues.append(f'Missing values in {col}: {count}')
duplicates = df.duplicated().sum()
if duplicates > 0:
    issues.append(f'Duplicate rows: {duplicates}')
for col in df.select_dtypes(include=['number']).columns:
    q1 = df[col].quantile(0.25)
    q3 = df[col].quantile(0.75)
    iqr = q3 - q1
    outliers = df[(df[col] < q1 - 1.5*iqr) | (df[col] > q3 + 1.5*iqr)].shape[0]
    if outliers > 0:
        issues.append(f'Outliers in {col}: {outliers}')
env['issues_report'] = {'file': ${item}, 'issues': issues}

import pandas as pd
df = ${repair_report}['repaired_df']
validation = []
missing = df.isnull().sum().sum()
if missing == 0:
    validation.append('No missing values remain')
else:
    validation.append(f'Warning: {missing} missing values remain')
duplicates = df.duplicated().sum()
if duplicates == 0:
    validation.append('No duplicates remain')
else:
    validation.append(f'Warning: {duplicates} duplicates remain')
env['validation_report'] = {'file': ${item}, 'validation': validation}

import pandas as pd
df = ${repair_report}['repaired_df']
stats = {}
for col in df.select_dtypes(include=['number']).columns:
    stats[col] = {
        'mean': float(df[col].mean()),
        'median': float(df[col].median()),
        'std': float(df[col].std()),
        'min': float(df[col].min()),
        'max': float(df[col].max())
    }
env['stats_report'] = {'file': ${item}, 'statistics': stats}

merged = {
    'files': ${all_file_results},
    'total_files': len(${all_file_results}),
    'summary': {
        'total_issues': sum(len(f['issues']['issues']) for f in ${all_file_results}),
        'total_repairs': sum(len(f['repairs']['repairs']) for f in ${all_file_results})
    }
}
env['merged_results'] = merged

review = {
    'overall_quality': 'PASS' if ${merged_results}['summary']['total_issues'] == 0 else 'REVIEW',
    'recommendations': [],
    'evidence_log': []
}
for f in ${merged_results}['files']:
    review['evidence_log'].append({
        'file': f['file'],
        'issues_found': len(f['issues']['issues']),
        'repairs_made': len(f['repairs']['repairs']),
        'validation_status': f['validation']['validation']
    })
if ${merged_results}['summary']['total_issues'] > 0:
    review['recommendations'].append('Some issues were detected and repaired. Review evidence log for details.')
env['quality_review'] = review

