          "description": "Detect schema drift, type errors, missing values, duplicates, and outliers",
          "code": "import pandas as pd\nimport numpy as np\ndf = pd.read_csv('${item}')\nschema = ${schema_report}\nissues = []\nmissing = df.isnull().sum()\nif missing.any():\n    issues.append('Missing values: ' + str(missing[missing > 0].to_dict()))\ndup_count = df.duplicated().sum()\nif dup_count > 0:\n    issues.append(f'Duplicate rows: {dup_count}')\nfor col in schema.get('columns', []):\n    col_name = col['name']\n    expected_type = col.get('type', '')\n    if col_name in df.columns:\n        if expected_type in ('Number', 'Integer') and not np.issubdtype(df[col_name].dtype, np.number):\n            issues.append(f'Type mismatch: {col_name} expected {expected_type} but got {df[col_name].dtype}')\nfor col in df.select_dtypes(include=[np.number]).columns:\n    q1 = df[col].quantile(0.25)\n    q3 = df[col].quantile(0.75)\n    iqr = q3 - q1\n    outlier_count = int(((df[col] < q1 - 1.5 * iqr) | (df[col] > q3 + 1.5 * iqr)).sum())\n    if outlier_count > 0:\n        issues.append(f'Outliers in {col}: {outlier_count}')\nenv['quality_report'] = {'file': '${item}', 'issues': issues, 'row_count': len(df), 'columns': list(df.columns)}",
