          }
        },
        {
          "name": "repair_data",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Repair recoverable data quality issues: deduplicate, fill missing, coerce types, cap outliers",
          "code": "import pandas as pd\nimport numpy as np\ndf = pd.read_csv('${item}')\nrepairs = []\nbefore = len(df)\ndf = df.drop_duplicates()\nafter = len(df)\nif before - after > 0:\n    repairs.append(f'Removed {before - after} duplicate rows')\nfor col in df.select_dtypes(include=[np.number]).columns:\n    missing_count = int(df[col].isnull().sum())\n    if missing_count > 0:\n        median_val = float(df[col].median())\n        df[col] = df[col].fillna(median_val)\n        repairs.append(f'Filled {missing_count} missing values in {col} with median {median_val:.2f}')\nfor col in df.columns:\n    if df[col].dtype == 'object':\n        coerced = pd.to_numeric(df[col], errors='coerce')\n        if coerced.notna().sum() > 0.8 * len(df):\n            df[col] = coerced\n            repairs.append(f'Coerced column {col} to numeric')\nfor col in df.select_dtypes(include=[np.number]).columns:\n    lower = df[col].quantile(0.01)\n    upper = df[col].quantile(0.99)\n    capped = int(((df[col] < lower) | (df[col] > upper)).sum())\n    if capped > 0:\n        df[col] = df[col].clip(lower=lower, upper=upper)\n        repairs.append(f'Capped {capped} outlier values in {col} to [{lower:.2f}, {upper:.2f}]')\nenv['repaired'] = {'file': '${item}', 'repairs': repairs, 'cleaned_rows': df.to_dict('records'), 'row_count': len(df)}",
          "inputBindings": [
            {"param": "quality_report", "source": "detect_quality_issues", "binding": "quality_report"}
          ],
          "output": {
            "name": "repaired_data",
            "typeName": "Record",
            "fields": [
              {"name": "file", "typeName": "String"},
              {"name": "repairs", "typeName": "List<String>"},
              {"name": "cleaned_rows", "typeName": "List<Record>"},
              {"name": "row_count", "typeName": "Integer"}
            ]
          }
        },
        {
          "name": "revalidate",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Revalidate repaired data to confirm issues are resolved",
          "code": "import pandas as pd\nimport numpy as np\ndf = pd.DataFrame(${repaired_data}['cleaned_rows'])\nremaining = []\nmissing = df.isnull().sum()\nif missing.any():\n    remaining.append('Remaining missing: ' + str(missing[missing > 0].to_dict()))\ndup_count = int(df.duplicated().sum())\nif dup_count > 0:\n    remaining.append(f'Remaining duplicates: {dup_count}')\nfor col in df.select_dtypes(include=[np.number]).columns:\n    q1 = df[col].quantile(0.25)\n    q3 = df[col].quantile(0.75)\n    iqr = q3 - q1\n    outlier_count = int(((df[col] < q1 - 1.5 * iqr) | (df[col] > q3 + 1.5 * iqr)).sum())\n    if outlier_count > 0:\n        remaining.append(f'Remaining outliers in {col}: {outlier_count}')\nenv['revalidation'] = {'file': '${item}', 'remaining_issues': remaining, 'passed': len(remaining) == 0}",
          "inputBindings": [
            {"param": "repaired_data", "source": "repair_data", "binding": "repaired_data"}
          ],
          "output": {
            "name": "revalidation_report",
            "typeName": "Record",
            "fields": [
