{
  "goal": "Analyze quarterly sales CSV files for data quality, repair recoverable issues, revalidate, compute statistics, merge results, run quality review, and generate a consolidated Markdown report with evidence log.",
  "steps": [
    {
      "name": "process_each_file",
      "kind": "foreach",
      "over": "inputs",
      "description": "Process each quarterly sales CSV file through detection, repair, revalidation, and statistics",
      "body": [
        {
          "name": "inspect_schema",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Inspect CSV schema and detect schema drift and type issues",
          "code": "import pandas as pd\ndf = pd.read_csv(${item})\nschema_report = {\n    'columns': [{'name': col, 'dtype': str(df[col].dtype)} for col in df.columns],\n    'row_count': len(df),\n    'issues': []\n}\nfor col in df.columns:\n    if df[col].dtype == 'object':\n        try:\n            pd.to_numeric(df[col])\n            schema_report['issues'].append(f'Column {col} might be numeric but is stored as object')\n        except:\n            pass\nenv['schema_report'] = schema_report",
          "inputBindings": [],
          "output": {
            "name": "schema_report",
            "typeName": "Record",
            "fields": [
              { "name": "columns", "typeName": "List" },
              { "name": "row_count", "typeName": "Integer" },
              { "name": "issues", "typeName": "List" }
            ]
          }
        },
        {
          "name": "detect_issues",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Detect data quality issues: missing values, duplicates, outliers",
          "code": "import pandas as pd\ndf = pd.read_csv(${item})\nissues = []\nmissing = df.isnull().sum()\nfor col, count in missing.items():\n    if count > 0:\n        issues.append(f'Missing values in {col}: {count}')\nduplicates = df.duplicated().sum()\nif duplicates > 0:\n    issues.append(f'Duplicate rows: {duplicates}')\nfor col in df.select_dtypes(include=['number']).columns:\n    q1 = df[col].quantile(0.25)\n    q3 = df[col].quantile(0.75)\n    iqr = q3 - q1\n    outliers = df[(df[col] < q1 - 1.5*iqr) | (df[col] > q3 + 1.5*iqr)].shape[0]\n    if outliers > 0:\n        issues.append(f'Outliers in {col}: {outliers}')\nenv['issues_report'] = {'file': ${item}, 'issues': issues}",
          "inputBindings": [],
          "output": {
            "name": "issues_report",
            "typeName": "Record",
            "fields": [
              { "name": "file", "typeName": "String" },
              { "name": "issues", "typeName": "List" }
            ]
          }
        },
        {
          "name": "repair_issues",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Repair recoverable issues: drop duplicates, fill missing values",
          "code": "import pandas as pd\ndf = pd.read_csv(${item})\nrepairs = []\nbefore = len(df)\ndf = df.drop_duplicates()\nafter = len(df)\nif before > after:\n    repairs.append(f'Dropped {before - after} duplicate rows')\nfor col in df.select_dtypes(include=['number']).columns:\n    if df[col].isnull().any():\n        median = df[col].median()\n        count = df[col].isnull().sum()\n        df[col] = df[col].fillna(median)\n        repairs.append(f'Filled {count} missing values in {col} with median {median}')\nenv['repair_report'] = {'file': ${item}, 'repairs': repairs, 'repaired_df': df}",
          "inputBindings": [],
          "output": {
            "name": "repair_report",
            "typeName": "Record",
            "fields": [
              { "name": "file", "typeName": "String" },
              { "name": "repairs", "typeName": "List" },
              { "name": "repaired_df", "typeName": "Any" }
            ]
          }
        },
        {
          "name": "revalidate",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Revalidate repaired data to confirm issues are resolved",
          "code": "import pandas as pd\ndf = ${repair_report}['repaired_df']\nvalidation = []\nmissing = df.isnull().sum().sum()\nif missing == 0:\n    validation.append('No missing values remain')\nelse:\n    validation.append(f'Warning: {missing} missing values remain')\nduplicates = df.duplicated().sum()\nif duplicates == 0:\n    validation.append('No duplicates remain')\nelse:\n    validation.append(f'Warning: {duplicates} duplicates remain')\nenv['validation_report'] = {'file': ${item}, 'validation': validation}",
          "inputBindings": [
            { "param": "repair_report", "source": "repair_issues", "binding": "repair_report" }
          ],
          "output": {
            "name": "validation_report",
            "typeName": "Record",
            "fields": [
              { "name": "file", "typeName": "String" },
              { "name": "validation", "typeName": "List" }
            ]
          }
        },
        {
          "name": "compute_stats",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Compute quarterly statistics for numeric columns",
          "code": "import pandas as pd\ndf = ${repair_report}['repaired_df']\nstats = {}\nfor col in df.select_dtypes(include=['number']).columns:\n    stats[col] = {\n        'mean': float(df[col].mean()),\n        'median': float(df[col].median()),\n        'std': float(df[col].std()),\n        'min': float(df[col].min()),\n        'max': float(df[col].max())\n    }\nenv['stats_report'] = {'file': ${item}, 'statistics': stats}",
          "inputBindings": [
            { "param": "repair_report", "source": "repair_issues", "binding": "repair_report" }
