          "output": {
            "name": "stats_report",
            "typeName": "Record",
            "fields": [
              { "name": "file", "typeName": "String" },
              { "name": "statistics", "typeName": "Any" }
            ]
          }
        },
        {
          "name": "compile_file_result",
          "kind": "primitive",
          "capability": "execute_python",
          "description": "Compile all results for this file into a single record",
          "code": "result = {\n    'file': ${item},\n    'schema': ${schema_report},\n    'issues': ${issues_report},\n    'repairs': ${repair_report},\n    'validation': ${validation_report},\n    'statistics': ${stats_report}\n}\nenv['file_result'] = result",
          "inputBindings": [
            { "param": "schema_report", "source": "inspect_schema", "binding": "schema_report" },
            { "param": "issues_report", "source": "detect_issues", "binding": "issues_report" },
            { "param": "repair_report", "source": "repair_issues", "binding": "repair_report" },
            { "param": "validation_report", "source": "revalidate", "binding": "validation_report" },
            { "param": "stats_report", "source": "compute_stats", "binding": "stats_report" }
