          "output": {
            "name": "file_result",
            "typeName": "Record",
            "fields": [
              { "name": "file", "typeName": "String" },
              { "name": "schema", "typeName": "Record" },
              { "name": "issues", "typeName": "Record" },
              { "name": "repairs", "typeName": "Record" },
              { "name": "validation", "typeName": "Record" },
              { "name": "statistics", "typeName": "Record" }
            ]
          }
        }
      ],
      "output": {
        "name": "all_file_results",
        "typeName": "List<Record>",
        "fields": [
          { "name": "file", "typeName": "String" },
          { "name": "schema", "typeName": "Record" },
          { "name": "issues", "typeName": "Record" },
          { "name": "repairs", "typeName": "Record" },
          { "name": "validation", "typeName": "Record" },
          { "name": "statistics", "typeName": "Record" }
