      "inputBindings": [
        { "param": "all_file_results", "source": "process_each_file", "binding": "all_file_results" }
      ],
      "output": {
        "name": "merged_results",
        "typeName": "Record",
        "fields": [
          { "name": "files", "typeName": "List<Record>" },
          { "name": "total_files", "typeName": "Integer" },
          { "name": "summary", "typeName": "Record" }
