      "inputBindings": [
        { "param": "merged_results", "source": "merge_results", "binding": "merged_results" }
      ],
      "output": {
        "name": "quality_review",
        "typeName": "Record",
        "fields": [
          { "name": "overall_quality", "typeName": "String" },
          { "name": "recommendations", "typeName": "List" },
          { "name": "evidence_log", "typeName": "List<Record>" }
        ]
      }
    },
    {
      "name": "generate_report",
      "kind": "primitive",
      "capability": "execute_python",
      "description": "Generate consolidated Markdown report with evidence log",
      "code": "report = '# Quarterly Sales Data Quality Report\\n\\n'\nreport += '## Summary\\n'\nreport += '- Total files processed: ' + str(${merged_results}['total_files']) + '\\n'\nreport += '- Total issues found: ' + str(${merged_results}['summary']['total_issues']) + '\\n'\nreport += '- Total repairs made: ' + str(${merged_results}['summary']['total_repairs']) + '\\n'\nreport += '- Overall quality: ' + str(${quality_review}['overall_quality']) + '\\n\\n'\nreport += '## Evidence Log\\n\\n'\nfor entry in ${quality_review}['evidence_log']:\n    report += '### ' + entry['file'] + '\\n'\n    report += '- Issues found: ' + str(entry['issues_found']) + '\\n'\n    report += '- Repairs made: ' + str(entry['repairs_made']) + '\\n'\n    report += '- Validation: ' + ', '.join(entry['validation_status']) + '\\n\\n'\nif ${quality_review}['recommendations']:\n    report += '## Recommendations\\n'\n    for rec in ${quality_review}['recommendations']:\n        report += '- ' + rec + '\\n'\nenv['final_report'] = report",
      "inputBindings": [
        { "param": "merged_results", "source": "merge_results", "binding": "merged_results" },
        { "param": "quality_review", "source": "quality_review", "binding": "quality_review" }
      ],
      "output": {
        "name": "final_report",
        "typeName": "String"
      }
    }
